import React, { useEffect, useState } from 'react';
import { Container, Nav, Navbar } from 'react-bootstrap';
import NavLink from '../NavAccess';
import { useNavigate } from 'react-router-dom';
import {
  accessCategories,
  accessTalents,
  accessEvents,
  accessPayments,
  accessOrders,
} from '../../const/access';
import { accessUsers } from '../../const/accessUsers';

function SNavbar() {
  const navigate = useNavigate();
  const [role, setRole] = useState(null);

  useEffect(() => {
    const fetchData = () => {
      let { role } = localStorage.getItem('auth')
        ? JSON.parse(localStorage.getItem('auth'))
        : {};

      setRole(role);
    };
    fetchData();
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    window.location.href = '/login';
  };

  return (
    <Navbar className='shadow-sm' style={{ background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' }}>
      <Container>
        <Navbar.Brand
          href='#home'
          className='fw-bold text-white'
          onClick={() => navigate('/')}
          style={{ cursor: 'pointer' }}
        >
          Semina Admin
        </Navbar.Brand>
        <Nav className='me-auto'>
          <NavLink
            role={role}
            roles={accessCategories.lihat}
            action={() => navigate('/')}
          >
            Home
          </NavLink>
          <NavLink
            role={role}
            roles={accessCategories.lihat}
            action={() => navigate('/categories')}
          >
            Categories
          </NavLink>
          <NavLink
            role={role}
            roles={accessTalents.lihat}
            action={() => navigate('/talents')}
          >
            Talents
          </NavLink>
          <NavLink
            role={role}
            roles={accessPayments.lihat}
            action={() => navigate('/payments')}
          >
            Payment
          </NavLink>
          <NavLink
            role={role}
            roles={accessEvents.lihat}
            action={() => navigate('/events')}
          >
            Events
          </NavLink>
          <NavLink
            role={role}
            roles={accessOrders.lihat}
            action={() => navigate('/orders')}
          >
            Orders
          </NavLink>
          <NavLink
            role={role}
            roles={accessUsers.lihat}
            action={() => navigate('/users')}
          >
            Users
          </NavLink>
        </Nav>
        <Nav className='justify-content-end'>
          <Nav.Link
            onClick={() => handleLogout()}
            className='text-white fw-medium'
          >
            Logout
          </Nav.Link>
        </Nav>
      </Container>
    </Navbar>
  );
}

export default SNavbar;
